func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/restaurants", wrapper.ListRestaurants)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/restaurants/{restaurantId}", wrapper.GetRestaurant)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/restaurants/{restaurantId}/menu", wrapper.GetRestaurantMenu)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v1/cart", wrapper.ClearCart)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/cart", wrapper.GetCart)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/cart/items", wrapper.SetCartItem)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/orders", wrapper.ListOrders)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/orders", wrapper.CreateOrder)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/orders/{orderId}", wrapper.GetOrder)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/orders/{orderId}/cancel", wrapper.CancelOrder)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/partner/v1/me", wrapper.PartnerGetProfile)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/partner/v1/me", wrapper.PartnerUpdateProfile)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/partner/v1/menu", wrapper.PartnerSyncMenu)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/partner/v1/menu/items/{externalId}", wrapper.PartnerUpdateMenuItem)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/partner/v1/orders", wrapper.PartnerListOrders)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/partner/v1/orders/{orderId}", wrapper.PartnerGetOrder)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/partner/v1/orders/{orderId}/accept", wrapper.PartnerAcceptOrder)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/partner/v1/orders/{orderId}/reject", wrapper.PartnerRejectOrder)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/partner/v1/orders/{orderId}/status", wrapper.PartnerUpdateOrderStatus)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/restaurants", wrapper.AdminCreateRestaurant)
	})

	return r
}

